mapper.update:
UPDATE student_points
SET last_checkin = #{date}, continuous_days = #{continuousDays}, update_time = NOW()
WHERE studentid = #{studentid}

mapper.select:
SELECT points, type, reason, create_time AS createTime
FROM points_log
WHERE studentid = #{studentid}
ORDER BY id DESC
LIMIT #{limit}

SELECT badge_code AS badgeCode, obtain_time AS obtainTime
FROM student_badge
WHERE studentid = #{studentid}

SELECT s.studentid AS studentid, s.studentname AS studentname, s.studentno AS studentno, ci.classname AS classname, IFNULL(sp.total_points, 0) AS totalPoints, IFNULL(sp.level, 1) AS level, IFNULL(sp.continuous_days, 0) AS continuousDays FROM student s LEFT JOIN student_points sp ON sp.studentid = s.studentid LEFT JOIN classinfo ci ON s.classid = ci.classid
AND s.classid = #{classid}
ORDER BY totalPoints DESC, continuousDays DESC LIMIT #{limit}
